insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Auxiliar de Control y Vigilancia Interna', 'Apoyar en el control y supervisión de accesos, resguardo de bienes materiales y verificación de cumplimiento de normas internas de seguridad, garantizando el orden y la protección en las instalaciones de la empresa.', 'Bachiller. 2 años en puesto similar. Manejo básico de cámaras de videovigilancia y alarmas. Uso adecuado de radios, teléfonos y habilidades para comunicar información clara y precisa.', 'ACCISA-02', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Gabriela Chan', 'Operativo', 'Q.4050.00', $json${"no_supervisa": "Ninguna", "posiciones_supervisa": "Ninguna", "funciones": [{"categoria": "Control de Accesos", "funcion": "Registrar y verificar el ingreso y salida de personal, visitantes y proveedores.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Control de Accesos", "funcion": "Revisar los sistemas de vigilancia electrónica y reportar cualquier anomalía.", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Control de Accesos", "funcion": "Velar por la integridad de equipos, herramientas y materiales en las instalaciones.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Prevención y apoyo en emergencias", "funcion": "Informar de manera inmediata a la jefatura sobre cualquier situación que ponga en riesgo la seguridad.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Prevención y apoyo en emergencias", "funcion": "Colaborar en simulacros, evacuaciones y procedimientos internos de prevención.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Prevención y apoyo en emergencias", "funcion": "Asegurar que se respeten las políticas y reglamentos establecidos por la empresa.", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Supervisión y monitoreo interno", "funcion": "Realizar recorridos periódicos por las áreas de trabajo, pasillos, bodegas y zonas comunes para verificar el orden y condiciones de seguridad interna.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Supervisión y monitoreo interno", "funcion": "Observar y reportar cualquier situación inusual o sospechosa.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Supervisión y monitoreo interno", "funcion": "Comprobar que puertas, ventanas y accesos restringidos permanezcan cerrados o bajo control.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Resguardo de bienes y materiales", "funcion": "Supervisar el traslado interno de materiales, herramientas o equipos para evitar extravíos.", "frecuencia": "Diario", "tiempo": "0.15"}, {"categoria": "Resguardo de bienes y materiales", "funcion": "Llevar control de la entrada y salida de mercancías en zonas autorizadas.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Resguardo de bienes y materiales", "funcion": "Custodiar bienes en áreas designadas hasta su entrega o traslado.", "frecuencia": "Diario", "tiempo": "0.15"}], "inversion_actividades": "100% ACCISA", "nivel_iniciativa": "Iniciativa: Media-Alta. Debe ser capaz de identificar situaciones inusuales o potenciales riesgos y actuar de inmediato siguiendo protocolos internos, incluso sin supervisión directa. Requiere proactividad para proponer mejoras en los procesos de control, registro y prevención de incidentes.", "toma_decisiones": "Medio: Tiene autoridad para detener temporalmente un ingreso si detecta irregularidades, hasta recibir instrucciones de su superior. Decide acciones inmediatas en casos de riesgo evidente (por ejemplo, activar una alarma, llamar a brigadas internas o contactar a emergencias).", "manejo_activos": "Acceso a cámaras de seguridad (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Chumpa Institucional. Gafete institucional.", "equipos_seguridad": "Arma de fuego", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico Moderado, requiere mantenerse de pie por períodos prolongados durante los recorridos y control de accesos. Movimientos frecuentes para realizar inspecciones en diferentes áreas (caminar, subir escaleras).\nNivel de Esfuerzo Mental Alto, Necesita mantener atención constante para detectar irregularidades y situaciones de riesgo. Capacidad para resolver problemas inmediatos bajo presión, siguiendo protocolos establecidos.", "perfil": {"edad": "18+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Bachiller", "formacion_complementaria": "N/A", "conocimientos_basicos": "Manejo básico de cámaras de videovigilancia y alarmas. Uso adecuado de radios, teléfonos y habilidades para comunicar información clara y precisa.", "habilidades_especificas": "Buenas relaciones humanas, vocación de servicio - requiere presencia física en la empresa. Organizada y capaz de manejar el tiempo efectivamente.", "conocimientos_informaticos": "Windows: Normal. Microsoft Office: Normal. Otras: Internet y Correo electrónico", "sistemas_especializados": "No indispensable", "beneficios": "A definir por la empresa", "se_requiere_viajar": "No", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto y liderazgo"}, "competencias_generales": [{"competencia": "Compromiso", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Conocimiento de protocolos de seguridad", "grado": "C"}, {"competencia": "Perseverancia en la Consecución de objetivos", "grado": "C"}, {"competencia": "Proactividad", "grado": "B"}, {"competencia": "Flexibilidad y adaptación a los cambios", "grado": "D"}], "competencias_especificas": [{"competencia": "Capacidad de Planificación y Organización", "grado": "B"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}, {"competencia": "Profundidad en el conocimiento de los productos", "grado": "C"}, {"competencia": "Productividad", "grado": "B"}, {"competencia": "Manejo del estrés", "grado": ""}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2025-07-18", "fecha_revision": "2025-08-25", "version": "Rev. 25.08.2025 — Ref. ACCISA-02"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Recepcionista y Auxiliar de Recursos Humanos', 'Garantizar una atención cordial, eficiente y oportuna a clientes internos y externos desde el área de recepción, gestionando llamadas, correspondencia, facturas, contraseñas de pago y solicitudes administrativas, así como brindar apoyo documental y operativo al área de Recursos Humanos en trámites de personal, IGSS, IRTRA, vacaciones, expedientes y planillas, contribuyendo al orden administrativo, la continuidad operativa y el cumplimiento de los procesos internos de la empresa.', 'Secretaria bilingüe, Perito Contador, Bachiller o carrera afín. 2 años en puesto similar. Servicio al cliente, comunicación clara, cordialidad, organización, seguimiento, atención al detalle, discreción, confidencialidad, manejo de varias tareas a la vez.', 'ACCISA-03', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Gabriela Chan', 'Administrativo', 'Q4,050.00', $json${"no_supervisa": "Mensajero", "posiciones_supervisa": "Ninguna", "funciones": [{"categoria": "Recepción y atención al cliente", "funcion": "Atender de forma cordial y oportuna a clientes internos y externos que se presenten o se comuniquen con la empresa, canalizando sus solicitudes según corresponda.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Atender la planta telefónica, recibiendo llamadas externas e internas, brindando orientación inicial y trasladando la comunicación al área o colaborador correspondiente.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Recibir y dar la bienvenida a los clientes que ingresen a las instalaciones, actuando como host o anfitrión de atención inicial.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Ofrecer al cliente algo de tomar, cuando aplique, procurando una atención amable, respetuosa y acorde a los estándares de servicio de la empresa.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Acompañar a los clientes al área de espera o guiarlos directamente con el asesor de ventas correspondiente, según el motivo de su visita.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Coordinar la atención inicial del cliente con los asesores de ventas o personal correspondiente, asegurando que la persona sea atendida de forma ordenada y oportuna.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Recepción y atención al cliente", "funcion": "Dar seguimiento a solicitudes de clientes recibidas por medio del WhatsApp de la empresa, respondiendo o canalizando los requerimientos según corresponda.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Recibir correspondencia física dirigida a la empresa, registrarla cuando aplique y trasladarla oportunamente a la persona o departamento correspondiente.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Llevar el control de contraseñas de pago, entregando facturas para solicitar contraseñas y apoyar el seguimiento de cobros correspondientes.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Entregar cheques a proveedores y empleados, conforme a las instrucciones recibidas y a la programación de pagos establecida.", "frecuencia": "Semanalmente", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Coordinar y planificar diariamente las rutas del mensajero, asegurando una distribución eficiente de las diligencias de acuerdo con las necesidades de la empresa.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Recibir, registrar y administrar todas las solicitudes de mensajería realizadas por las diferentes áreas, verificando que la información esté completa antes de asignarlas.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Clasificar las diligencias según su nivel de prioridad (Alta, Media o Baja), estableciendo el orden de ejecución para optimizar los tiempos de respuesta.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Llevar el control de entradas y salidas del mensajero, registrando la hora de salida, hora de retorno, destino, motivo de la diligencia y área solicitante.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Resguardar y mantener actualizado el registro de todas las diligencias realizadas, generando controles que permitan medir tiempos de respuesta, cumplimiento y productividad del servicio de mensajería.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Reportar oportunamente cualquier anomalía relacionada con las actividades del mensajero, incluyendo retrasos, incumplimientos, incidentes o necesidades de mantenimiento de los recursos asignados.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Correspondencia y documentación", "funcion": "Rebajar en el sistema los recibos de pago de clientes, asegurando que el registro administrativo quede actualizado conforme a los pagos recibidos.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Archivo y control documental", "funcion": "Archivar copias de facturas de ventas de IMISA, ISSA y ACCISA, manteniendo el orden documental para consulta, control interno y envío posterior a Contabilidad.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Archivo y control documental", "funcion": "Preparar y entregar documentación de facturas a Contabilidad y archivo, conforme al cierre o revisión mensual correspondiente.", "frecuencia": "Semanalmente", "tiempo": ""}, {"categoria": "Archivo y control documental", "funcion": "Armar expediente físico y en sistema de cada nuevo colaborador, manteniéndolo actualizado.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Archivo y control documental", "funcion": "Llevar el control y trasladar al departamento contable los documentos que se reciban con relación a: embargos, pensiones alimenticias, préstamos, otros.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Elaborar certificados de IGSS solicitados por los colaboradores o requeridos para trámites administrativos de personal.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Colaborar en conjunto con Gerencia de Recursos Humanos, en la elaboración y ejecución de planes, programas y actividades propias del departamento.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Apoyo en las campañas de cultura a realizar así como capacitación y seguimiento de todo lo relacionado con SSO.", "frecuencia": "Semanalmente", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Emitir solicitudes de vacaciones de los colaboradores, apoyando el control documental del proceso.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Elaborar recibos de bonificaciones por calificación y trasladarlos a la persona encargada para la entrega del dinero en efectivo a los instaladores.", "frecuencia": "Mensualmente", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Entregar a fin de mes los recibos de pago de planilla de las 4 empresas, en original firmado para Contabilidad y copia para el empleado.", "frecuencia": "Mensualmente", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Apoyo en coordinación de eventos y celebraciones (Día del Contador, de la Madre, del Padre, Convivio Navideño, distinciones a colaboradores con años de experiencia).", "frecuencia": "Mensualmente", "tiempo": ""}, {"categoria": "Apoyo a Recursos Humanos", "funcion": "Entregar solicitudes de trabajo a candidatos o personas interesadas, conforme al proceso interno de ingreso de personal.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Apoyo Administrativo", "funcion": "Elaborar el reporte del Informe al Empleador del Ministerio de Trabajo, según los requerimientos administrativos aplicables.", "frecuencia": "Mensualmente", "tiempo": ""}, {"categoria": "Apoyo Administrativo", "funcion": "Cotizar productos para uso del departamento de Taller y Don César, conforme a las solicitudes recibidas.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Apoyo Administrativo", "funcion": "Cotizar solicitudes relacionadas con Recursos Humanos, conforme a las necesidades del área.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Apoyo Administrativo", "funcion": "Velar porque las políticas internas se cumplan en la organización.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Apoyo Administrativo", "funcion": "Revisar y mandar correo a los cumpleañeros del mes.", "frecuencia": "Diario", "tiempo": ""}], "inversion_actividades": "50% ACCISA, 25% ISSA, 15% IMISA, 10% IERSA", "nivel_iniciativa": "Media. Debe atender, orientar y canalizar clientes, llamadas, documentos y solicitudes administrativas, aplicando los procesos internos establecidos. Puede gestionar actividades operativas de recepción y seguimiento documental, pero debe escalar casos que requieran autorización, manejo de información confidencial, pagos, cheques, facturas o decisiones propias de Recursos Humanos y Gerencia.", "toma_decisiones": "Media. Toma decisiones operativas relacionadas con la atención inicial del cliente, canalización de llamadas, orientación de visitantes, traslado de correspondencia, seguimiento de solicitudes y priorización de tareas diarias. No toma decisiones finales sobre pagos, planillas, trámites laborales, autorizaciones administrativas o información confidencial de colaboradores.", "equipos_trabajo": "Planta telefónica, computadora, WhatsApp empresarial, documentos administrativos, correspondencia, facturas, contraseñas de pago, expedientes y archivo físico o digital, según aplique.", "equipos_seguridad": "No se especifica responsabilidad directa sobre seguridad física, armas, valores o resguardo de bienes.", "condiciones_trabajo": "El puesto se desarrolla principalmente en un ambiente de oficina y recepción, con atención presencial a clientes, comunicación telefónica, seguimiento por WhatsApp empresarial, manejo de documentación administrativa y coordinación constante con diferentes áreas internas. El cargo requiere trato frecuente con clientes internos, clientes externos, proveedores, colaboradores y personal administrativo, por lo que demanda buena presentación, cordialidad, orden, discreción y capacidad de seguimiento.", "esfuerzo_fisico_mental": "Bajo. El puesto es principalmente administrativo y de recepción. Puede requerir desplazamientos internos para recibir clientes, guiarlos al área de espera, acompañarlos con el asesor correspondiente, trasladar correspondencia o entregar documentación.\nMedio. Requiere concentración, orden y atención al detalle para manejar llamadas, visitantes, WhatsApp empresarial, facturas, contraseñas de pago, correspondencia, archivo, expedientes y trámites de apoyo a Recursos Humanos. También exige discreción en el manejo de información relacionada con colaboradores.", "perfil": {"edad": "18+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Secretaria bilingüe, Perito Contador, Bachiller o carrera afín", "formacion_complementaria": "Estudiante de Psicología Industrial, Admón de Empresas", "conocimientos_basicos": "Atención al cliente, recepción, manejo de llamadas telefónicas, seguimiento de solicitudes, control de documentos, correspondencia, facturas, contraseñas de pago, archivo y apoyo administrativo básico a Recursos Humanos.", "habilidades_especificas": "Servicio al cliente, comunicación clara, cordialidad, organización, seguimiento, atención al detalle, discreción, confidencialidad, manejo de varias tareas a la vez y orientación al orden administrativo.", "conocimientos_informaticos": "Manejo básico de computadora, WhatsApp empresarial y herramientas administrativas de oficina. Microsoft Office: Alto", "sistemas_especializados": "No indispensable", "beneficios": "Sábado libre por cumpleaños, parqueo", "se_requiere_viajar": "No", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": ""}, "competencias_generales": [{"competencia": "Compromiso", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Conocimiento de protocolos de seguridad", "grado": ""}, {"competencia": "Perseverancia en la Consecución de objetivos", "grado": "C"}, {"competencia": "Proactividad", "grado": "B"}, {"competencia": "Flexibilidad y adaptación a los cambios", "grado": ""}], "competencias_especificas": [{"competencia": "Capacidad de Planificación y Organización", "grado": "B"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": ""}, {"competencia": "Profundidad en el conocimiento de los productos", "grado": "C"}, {"competencia": "Productividad", "grado": "B"}, {"competencia": "Manejo del estrés", "grado": ""}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-05-15", "fecha_revision": "2025-06-11", "version": "Rev. 11.06.2026 — Ref. ACCISA-03"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Asistente de Gerencia General y Financiera', 'Brinda asistencia a la Gerencia General y Financiera, en la gestión administrativa, comercial y de importaciones de Accesorios Ilimitados y de las empresas de Grupo IMISA, administrando documentación, pagos, facturación, contratos, proveedores, servicios, comunicaciones y procesos de importación, para dar seguimiento a los requerimientos y contribuir a la continuidad de las operaciones.', 'Graduado de nivel diversificado en Perito Contador, Secretaria bilingüe, Perito en Administración o carrera afín. 2 años en puesto similar. Capacidad de análisis, planificación, organización, priorización, negociación, seguimiento, comunicación efectiva, resolución de problemas, manejo de información confidencial.', 'ACCISA-006', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Licda. Miriam de Ríos', 'Administrativo', 'Q5,500.00 Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Gestión Documental de Importaciones", "funcion": "Gestión completa de importaciones, elaborar, procesar, organizar y controlar la documentación de importaciones aéreas, marítimas y terrestres de ACCISA, ISSA e IMISA, incluyendo conocimientos de embarque, facturas comerciales, listas de empaque y carta de traducción cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental de Importaciones", "funcion": "Revisar documentos comerciales y de soporte, prepólizas, seguros, cartas porte, BL y demás documentos requeridos, y verificar el cumplimiento de regulaciones aduaneras con apoyo del agente aduanal.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental, Legal y de Seguros", "funcion": "Manejar y actualizar documentos legales de IMISA, ISSA, ACCISA e IERSA; renovar pólizas de seguros de vehículos del Grupo IMISA y gestionar el pago de impuestos de circulación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Documental, Legal y de Seguros", "funcion": "Gestionar trámites de traspaso de vehículos y la finalización de contratos de ARREND, siguiendo las instrucciones y documentos requeridos para el traspaso.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Emitir facturación de IERSA por arrendamiento y servicios.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Emitir y enviar estados de cuenta de clientes del Grupo IMISA.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Coordinar pagos de tarjetas de crédito del Sr. César Ríos y otros pagos solicitados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Imprimir y dar seguimiento a facturas de TIGO y CLARO, trasladarlas para pago y controlar facturas de ARREND, Acceso Digital, TSP, Cash Logistic, Barrascout, ANCARSA, LEOS, Click Logistic y otros proveedores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación, Estados de Cuenta y Pagos", "funcion": "Controlar pagos de Casa Ensenada y Escuintla y gestionar el requerimiento trimestral de pago de IUSI de edificios del Grupo IMISA y del Sr. César Ríos, incluyendo IUSI Escuintla.", "frecuencia": "", "tiempo": ""}, {"categoria": "Apoyo Contable y Financiero", "funcion": "Preparar mensualmente la documentación contable del Sr. César Ríos e importaciones para Contabilidad y trasladarla a la Licda. Miriam de Ríos para revisión.", "frecuencia": "", "tiempo": ""}, {"categoria": "Apoyo Contable y Financiero", "funcion": "Actualizar datos de cuentas bancarias empresariales en dólares y quetzales, enviar transferencias al exterior y cubrir el área de Asistente Financiera cuando sea requerido.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Gestionar la compra de cojinetes para IMISA zona 4, solicitando autorización y el pedido correspondiente con el proveedor.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Controlar mantenimientos de filtros, purificador de agua, elevador, cámaras, aire acondicionado, impresoras y EGSSA, y trasladar las facturas a contabilidad para pago.", "frecuencia": "", "tiempo": ""}, {"categoria": "Mantenimientos, Telecomunicaciones y Suscripciones", "funcion": "Gestionar renovaciones, cancelaciones o adquisiciones de dispositivos y planes TIGO para ACCISA e ISSA y renovar la suscripción de Prensa Libre del Sr. César Ríos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Asistencia a Gerencia, Ventas y Recepción", "funcion": "Cubrir el área de recepción durante una hora, apoyar la planta telefónica y asistir a ventas con cotizaciones para agencias y clientes, cartas y seguimiento de productos de importación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Asistencia a Gerencia, Ventas y Recepción", "funcion": "Administrar los correos electrónicos de ACCISA, IMISA, IERSA e ISSA y brindar asistencia directa a Gerencia General en las actividades administrativas y operativas solicitadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Mantener contacto con proveedores internacionales, agentes de carga, navieras, SAT, agentes aduanales, transportistas, agentes de seguridad y demás partes involucradas para dar fluidez al proceso.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Negociar y coordinar transportistas y almacenes fiscales para liberaciones y traslado de mercancía de puerto a bodega, cuidando costos y tiempos; coordinar con bodega la salida y descarga de pedidos completos de ISSA cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Gestionar pagos de fletes, aranceles, impuestos, almacenajes y otros gastos; coordinar pagos con compras y contabilidad; dar seguimiento a liberaciones y envíos; preparar hojas de gastos; verificar la mercancía recibida y reportar discrepancias o daños.", "frecuencia": "", "tiempo": ""}], "nivel_iniciativa": "Iniciativa: Media-Alta. Debe organizar, priorizar y dar seguimiento a actividades administrativas, financieras y operativas de manera simultánea. Gestionar documentación, controlar fechas de pago y vencimiento, preparar reportes, actualizar información bancaria, coordinar trámites, dar seguimiento a proveedores y resolver incidencias operativas relacionadas con pagos, servicios e importaciones.", "toma_decisiones": "Cuenta con autonomía para comunicarse y coordinar con proveedores internacionales, navieras, agentes de carga, transportistas, agentes aduanales, SAT, bancos y áreas internas, así como para monitorear envíos, revisar documentación, identificar discrepancias y solicitar las correcciones correspondientes. No está autorizada para colocar pedidos sin autorización previa del Gerente General.", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Gafete institucional.", "equipos_seguridad": "Acceso al sistema ERP o sistema de ventas", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico Medio, El puesto requiere permanecer sentado durante períodos prolongados para realizar actividades administrativas, financieras y documentales, así como movilizarse entre las áreas de Gerencia, Ventas, Recepción, Caja, Contabilidad y Bodega para entregar documentos, coordinar pagos, efectuar trámites y dar seguimiento a distintas gestiones. También implica el uso constante de computadora, teléfono, impresora y otros recursos de oficina. De manera eventual, puede requerir trasladarse para efectuar trámites bancarios, administrativos o relacionados con importaciones.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español/ Inglés", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Secretaria bilingüe, Perito en Administración o carrera afín.", "formacion_complementaria": "Estudiante de Administración de Empresas, Contaduría Pública y Auditoría, Finanzas, Comercio Internacional, Administración Aduanera o carrera afín.", "conocimientos_basicos": "Control y programación de pagos; emisión y seguimiento de facturas; elaboración de estados de cuenta; manejo de cuentas bancarias; control de contratos, seguros y servicios; preparación de documentación contable; gestión de compras; trámites de vehículos; control de saldos, anticipos y pólizas de importación.", "habilidades_especificas": "Capacidad de análisis, planificación, organización, priorización, negociación, seguimiento, comunicación efectiva, resolución de problemas, manejo de información confidencial, atención al detalle y coordinación de múltiples actividades.", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "De preferencia sí (transporte)", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": ""}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-006"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Asistente Financiero', 'Gestiona los procesos financieros y administrativos de las empresas mediante el control de pagos, cheques, registros bancarios, documentación contable, obligaciones fiscales, cajas chicas, inventarios, facturación y procesos relacionados, procurando la integridad de la información contribuyendo a la eficiencia operativa.', 'Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín. 2 años en puesto similar. Manejo responsable y confidencial de información financiera.', 'ACCISA-007', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Licda. Miriam de Ríos', 'Administrativo', 'Q5,600.00 Base + Bonificación', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Gestión de Pagos y Cheques", "funcion": "Emitir cheques para las cuatro empresas según requerimientos autorizados; solicitar claves y gestionar las firmas autorizadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión de Pagos y Cheques", "funcion": "Entregar cheques a proveedores y colaboradores y elaborar los reportes de cheques emitidos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Financiero y Contable", "funcion": "Registrar los débitos bancarios en el sistema y validar que las transacciones cuenten con respaldo documental, especialmente facturas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control Financiero y Contable", "funcion": "Preparar la papelería contable quincenal y mensual, y controlar y archivar la documentación contable.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Verificar las facturas con retención de ISR y generar, descargar e imprimir las retenciones correspondientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Elaborar formularios, declaraciones juradas y reportes requeridos para los pagos fiscales.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Realizar el control mensual de retenciones para evitar omisiones y elaborar reportes consolidados para gerencia.", "frecuencia": "", "tiempo": ""}, {"categoria": "Gestión Fiscal (ISR e IVA) y Cumplimiento", "funcion": "Gestionar retenciones de ISR e IVA con las entidades correspondientes, controlar retenciones a empleados y generar los pagos respectivos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Gastos, Cajas Chicas y Servicios", "funcion": "Archivar y controlar órdenes, vouchers y papelería contable, y coordinar el envío de documentos y garantías a bodega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Gastos, Cajas Chicas y Servicios", "funcion": "Controlar insumos críticos, como cheques y talonarios, y gestionar solicitudes ante imprentas y bancos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Control de Inventarios", "funcion": "Revisar y validar los inventarios de tres empresas, comparar la información del sistema con bodega y detectar inconsistencias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación y Apoyo en Caja", "funcion": "Emitir facturas, efectuar cobros a clientes en efectivo, tarjeta o Visacuotas y entregar efectivo contra vale autorizado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación y Apoyo en Caja", "funcion": "Apoyar el control de los reportes de caja, incluyendo la revisión de facturas emitidas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Órdenes de Instalación", "funcion": "Emitir órdenes de instalación para instaladores, revisar y validar órdenes firmadas y verificar la liquidación previa a facturar.", "frecuencia": "", "tiempo": ""}, {"categoria": "Órdenes de Instalación", "funcion": "Clasificar órdenes dentro y fuera de propuesta, elaborar reportes semanales, dar seguimiento a contraseñas de facturación y coordinar órdenes pendientes.", "frecuencia": "", "tiempo": ""}, {"categoria": "Importaciones y Gerencia", "funcion": "Apoyo eventual en la gestión de procesos de importación, coordinar con navieras, proveedores y logística, contratar seguros y dar seguimiento hasta la entrega en bodega, reportando a gerencia.", "frecuencia": "Eventual", "tiempo": ""}, {"categoria": "Importaciones y Gerencia", "funcion": "Apoyo eventual a gerencia en tareas administrativas y operativas.", "frecuencia": "Eventual", "tiempo": ""}, {"categoria": "Apoyo Recepción", "funcion": "Dar seguimiento a proveedores y contraseñas de pago; atender clientes y llamadas; registrar clientes; apoyar al equipo comercial y a caja; actualizar reportes financieros y coordinar con distintas áreas.", "frecuencia": "Eventual", "tiempo": ""}], "inversion_actividades": "Complejidad alta por la combinación de pagos y cheques para cuatro empresas, controles contables y fiscales, revisión de inventarios de tres empresas, facturación, caja, documentación, importaciones y apoyo transversal. Las atribuciones requieren exactitud, seguimiento de plazos y manejo simultáneo de actividades.", "nivel_iniciativa": "Iniciativa: Media. Debe llevar el control, organización, atención al detalle, trabajo bajo presión, multitarea y adaptabilidad. No posee autoridad para autorizar pagos; las decisiones que requieran autorización deberán escalarse al Gerente Financiero.", "toma_decisiones": "Baja: Valida respaldos documentales, revisa facturas y retenciones, detecta inconsistencias, da seguimiento a pendientes y coordina gestiones con áreas internas y entidades externas.", "riesgos": "Riesgo de errores u omisiones en cheques, pagos, débitos bancarios, retenciones, declaraciones, facturación, caja, inventarios y documentación contable", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Gafete institucional.", "equipos_seguridad": "Acceso al sistema ERP o sistema de ventas. Cheques en blanco.", "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Perito en Administración o carrera afín.", "formacion_complementaria": "Estudios en Contaduría Pública y Auditoría", "conocimientos_basicos": "Poseer lógica matemática, demostrar competencias como organización, atención al detalle para evitar errores.", "habilidades_especificas": "Manejo responsable y confidencial de información financiera", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, responsabilidad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": ""}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. 05.08.2026 — Ref. ACCISA-007"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();

insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Mecánico Instalador', 'Ejecuta la instalación, ensamblaje y adaptación de los accesorios comercializados por Accesorios Ilimitados, utilizando correctamente las herramientas y materiales asignados, protegiendo la integridad de los vehículos y asegurando un trabajo ordenado, funcional y de calidad tanto en el centro de instalaciones como en agencias y bodegas de vehículos.', 'Graduado de nivel diversificado, preferentemente Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín. 2 años en puesto similar. Atención al detalle, habilidad manual, resolución de problemas, trabajo en equipo, orden y limpieza.', 'ACCISA-009', 'ACCISA', 'Operativa', 'Operativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Juan Luis Monzón / Bernardo Constanza', 'Operativo', 'Q4,050.00 Base + Bonificación Q250.00', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Preparación de Herramientas y Materiales", "funcion": "Preparar al inicio de la jornada los materiales, herramientas y elementos necesarios para ejecutar las instalaciones asignadas.", "frecuencia": "", "tiempo": ""}, {"categoria": "Preparación de Herramientas y Materiales", "funcion": "Revisar la disponibilidad de materiales y solicitar oportunamente los que estén próximos a agotarse para evitar interrupciones en el trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Preparación de Herramientas y Materiales", "funcion": "Mantener completa y disponible la herramienta necesaria para realizar el trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Revisar minuciosamente el vehículo antes de iniciar el trabajo e identificar y reportar cualquier desperfecto o condición preexistente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Informar inmediatamente al jefe inmediato cuando el vehículo no se encuentre listo para ser intervenido, para que se determine si corresponde esperar o regresar a la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Revisión y Recepción del Vehículo", "funcion": "Proteger y cuidar el vehículo durante todo el proceso de instalación para prevenir daños o reclamos posteriores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Instalar los accesorios comercializados por la empresa en el centro de instalaciones, agencias establecidas y bodegas de vehículos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Armar los accesorios antes de instalarlos y realizar las modificaciones necesarias en piezas o componentes cuando el trabajo lo requiera.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Elaborar las piezas y bases necesarias para las instalaciones, incluyendo actividades de lijado y pintura cuando corresponda.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Ejecutar el armado, instalación y mantenimiento de exhibiciones, muebles y accesorios destinados a las salas de ventas, agencias y eventos comerciales, verificando que su presentación cumpla con los estándares de calidad, imagen y exhibición establecidos por la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalación, Ensamblaje y Adaptación", "funcion": "Comunicar al jefe inmediato cuando no cuente con la capacidad técnica para realizar un trabajo, a fin de que se asigne a una persona calificada.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Trasladarse en el transporte designado por la empresa para realizar instalaciones en agencias ubicadas en la capital y municipios aledaños.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Ejecutar las instalaciones externas conforme a las indicaciones recibidas y retornar a la empresa en el transporte asignado.", "frecuencia": "", "tiempo": ""}, {"categoria": "Instalaciones Externas y Desplazamientos", "funcion": "Coordinar en el lugar de trabajo las condiciones necesarias para iniciar la instalación y evitar tiempos improductivos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Velar por la correcta instalación y funcionamiento de los accesorios para prevenir reclamos y retrabajos.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Llenar y firmar el informe correspondiente a los trabajos realizados fuera de la empresa, detallando lo sucedido durante la instalación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Calidad, Documentación y Reporte", "funcion": "Informar oportunamente al jefe inmediato sobre incidentes, limitaciones técnicas, condiciones del vehículo o situaciones que puedan afectar la calidad y el tiempo del trabajo.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Mantener limpia y ordenada el área de trabajo, en coordinación con los demás mecánicos instaladores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Apoyar en la limpieza de las instalaciones de uso general y de los vehículos de la empresa, según la organización interna.", "frecuencia": "", "tiempo": ""}, {"categoria": "Orden, Limpieza y Cuidado de Activos", "funcion": "Cuidar las herramientas, materiales, accesorios y demás activos utilizados durante las instalaciones.", "frecuencia": "", "tiempo": ""}, {"categoria": "Otros", "funcion": "Realizar las demás atribuciones delegadas por el jefe inmediato que sean necesarias para el cumplimiento del puesto.", "frecuencia": "", "tiempo": ""}], "inversion_actividades": "Complejidad media-alta por la variedad de vehículos, accesorios y condiciones de instalación, así como por la necesidad de revisar previamente cada unidad, ensamblar o modificar piezas, utilizar diferentes herramientas, desplazarse a agencias y asegurar que el trabajo quede funcional y sin daños. El puesto requiere precisión técnica, cuidado de activos, cumplimiento de tiempos y capacidad para reconocer cuándo una tarea debe ser escalada.", "nivel_iniciativa": "Iniciativa: Media-Alta. Debe demostrar iniciativa para preparar sus herramientas y materiales, anticipar faltantes, inspeccionar los vehículos, identificar desperfectos, organizar el trabajo y comunicar oportunamente cualquier condición que pueda afectar la instalación.", "manejo_activos": "Vehículos de clientes y de agencias durante la intervención; accesorios, piezas, materiales, herramientas manuales y eléctricas, equipos de prueba, órdenes e informes de instalación, áreas de trabajo y vehículos de la empresa utilizados para el traslado.", "equipos_trabajo": "Uniforme corporativo, gafete institucional, caja de herramientas completa, herramientas manuales y eléctricas requeridas según el tipo de instalación, equipo básico de medición o prueba y materiales autorizados para ensamblaje, modificación, lijado y pintura.", "equipos_seguridad": "Calzado de seguridad, lentes de protección y guantes adecuados al trabajo. Protección respiratoria y auditiva cuando se realicen actividades de lijado, pintura o uso de herramientas que generen polvo o ruido. Equipamiento sujeto a la evaluación y dotación de Seguridad y Salud Ocupacional.", "condiciones_trabajo": "El puesto se desarrolla en el centro de instalaciones, talleres, agencias y bodegas de vehículos, con desplazamientos en el transporte designado por la empresa hacia la capital y municipios aledaños. Requiere permanecer de pie durante períodos prolongados, trabajar dentro y alrededor de vehículos, agacharse, arrodillarse, inclinarse y utilizar herramientas manuales o eléctricas. Puede estar expuesto a ruido, polvo, grasas, pintura y variaciones de temperatura propias del taller o de instalaciones externas. Debe mantener orden, limpieza y cuidado constante del vehículo intervenido.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico: Alto. El puesto requiere permanecer de pie durante gran parte de la jornada, adoptar posturas de agachado, arrodillado o inclinado, trabajar en espacios reducidos dentro de los vehículos, manipular herramientas, accesorios, piezas y materiales, y desplazarse a agencias o bodegas para realizar instalaciones.\nNivel de esfuerzo mental: Alto. Requiere concentración sostenida para inspeccionar el vehículo, interpretar los requerimientos de instalación, seleccionar herramientas y materiales, proteger sistemas eléctricos y componentes, identificar daños preexistentes y verificar que el accesorio funcione correctamente.", "perfil": {"edad": "18+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado, preferentemente Técnico o Perito en Mecánica Automotriz, Electricidad Automotriz, Electromecánica o carrera afín.", "formacion_complementaria": "Cursos en instalación de accesorios para vehículos, electricidad automotriz, uso seguro de herramientas, prevención de daños, Seguridad y Salud Ocupacional y manejo de extintores.", "conocimientos_basicos": "Mecánica y electricidad automotriz básica; instalación y conexión de accesorios.", "habilidades_especificas": "Atención al detalle, habilidad manual, resolución de problemas, comunicación efectiva, trabajo en equipo, orden y limpieza, adaptación a distintos vehículos, orientación a la calidad y cuidado de bienes del cliente.", "conocimientos_informaticos": "Manejo básico de teléfono inteligente, mensajería y herramientas de registro digital cuando sean utilizadas para coordinar o documentar instalaciones.", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Responsabilidad, integridad, compromiso, respeto, puntualidad, orden y cuidado de los vehículos.", "otros": "Disponibilidad para trabajar en instalaciones externas y para utilizar el equipo de protección personal requerido según la tarea."}, "competencias_generales": [{"competencia": "Responsabilidad", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Orden y limpieza", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}], "competencias_especificas": [{"competencia": "Instalación de accesorios", "grado": "A"}, {"competencia": "Inspección y cuidado del vehículo", "grado": "A"}, {"competencia": "Control de calidad", "grado": "A"}, {"competencia": "Electricidad y mecánica automotriz", "grado": "A"}, {"competencia": "Uso seguro de herramientas", "grado": "B"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Supervisor de Taller", "fecha_elaboracion": "2026-07-25", "fecha_revision": "2026-08-05", "version": "Rev. Ref. ACCISA-009"}$json$::jsonb)
on conflict (puesto) do update set
  descripcion = excluded.descripcion,
  requisitos = excluded.requisitos,
  codigo = excluded.codigo,
  empresa = excluded.empresa,
  area = excluded.area,
  departamento = excluded.departamento,
  lugar_trabajo = excluded.lugar_trabajo,
  jefe_inmediato = excluded.jefe_inmediato,
  nivel_jerarquico = excluded.nivel_jerarquico,
  salario = excluded.salario,
  detalle = excluded.detalle,
  updated_at = now();
